import type {ToolDefinition} from '../../types/ai.js';
import {ToolRegistry} from './registry.js';

describe('Dynamic input validation [specs/hal-engine-tool-input-validation/spec.md#9]', () => {
  it('rejects missing units when the current definition requires them', async () => {
    const registry = new ToolRegistry();
    let definition: ToolDefinition = {
      name: 'weather',
      description: 'Weather forecast',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    };
    registry.register(() => definition, async input => JSON.stringify(input));
    const input = {location: 'Berlin'};

    expect(await registry.execute('weather', input)).toEqual({result: JSON.stringify(input)});
    definition = {
      ...definition,
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}, units: {type: 'string'}},
        required: ['location', 'units'],
      },
    };

    const response = await registry.execute('weather', input);

    expect(response.result).toMatch(/required.*units|units.*required/);
  });
});
EOF
